<div class="top"><div><h2 style="margin:0"><?= e($i['name']) ?> <?= inv_low($i) ? badge('Reorder', 'p-bad') : '' ?></h2><span class="muted"><?= e(STOCK_CATEGORIES[$i['category']]) ?><?= $i['sku'] ? ' · ' . e($i['sku']) : '' ?><?= $i['material'] ? ' · ' . e($i['material']) : '' ?><?= $i['color'] ? ' · ' . e($i['color']) : '' ?></span></div><div><a class="btn alt sm" href="/staff/inventory">← All</a><?php if (can('stock.manage')): ?> <a class="btn alt sm" href="/staff/inventory/<?= (int) $i['id'] ?>?edit=1">Edit</a><?php endif; ?></div></div>
<?php if ($edit): ?><div class="card mb"><h3>Edit item</h3><form method="post" action="/staff/inventory/<?= (int) $i['id'] ?>"><?= csrf_field() ?><?php require __DIR__ . '/inventory_fields.php'; ?>
<label style="font-weight:400"><input type="checkbox" name="archive" value="1" style="width:auto;margin:0 6px 0 0">Archive this item (hide it from the list)</label><button class="btn">Save</button></form></div><?php endif; ?>
<div class="grid g2" style="align-items:start">
<div><div class="card mb"><h3>Stock</h3><div class="kpi" style="grid-template-columns:1fr 1fr;margin:0"><div class="card"><span class="muted">In stock</span><b class="<?= inv_low($i) ? 'overdue' : '' ?>"><?= e(rtrim(rtrim($i['qty'], '0'), '.') ?: '0') ?></b><span class="muted"><?= e($i['unit']) ?></span></div><div class="card"><span class="muted">Reorder at</span><b><?= e(rtrim(rtrim($i['reorder_level'], '0'), '.') ?: '0') ?></b></div></div>
<dl class="kv mt"><dt>Location</dt><dd><?= e($i['location'] ?? '—') ?></dd><dt>Supplier</dt><dd><?= e($i['supplier'] ?? '—') ?></dd><dt>Unit cost</dt><dd><?= e(money($i['unit_cost'])) ?></dd><dt>Notes</dt><dd><?= $i['notes'] ? nl2br(e($i['notes'])) : '—' ?></dd></dl></div>
<?php if (can('stock.use')): ?><div class="card"><h3>Record movement</h3><form method="post" action="/staff/inventory/<?= (int) $i['id'] ?>/move"><?= csrf_field() ?>
<label>What happened</label><select name="reason"><?php foreach (STOCK_REASONS as $k => $l): if (in_array($k, ['purchase', 'adjust'], true) && !can('stock.manage')) continue; ?><option value="<?= e($k) ?>" <?= $k === 'use' ? 'selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select>
<label>Quantity (for a stock-take correction: the counted total)</label><input name="amount" inputmode="decimal" required>
<label>Order ref (optional, e.g. IS-0001)</label><input name="request_ref" maxlength="20"><label>Note</label><input name="note" maxlength="300"><button class="btn">Record</button></form></div><?php endif; ?></div>
<div class="card"><h3>Movement history</h3><div class="tw"><table><tr><th>When</th><th>Change</th><th>After</th><th>Why</th><th>By</th></tr>
<?php foreach ($moves as $m): ?><tr><td><?= e(fmt_dt($m['created_at'])) ?></td><td class="<?= (float) $m['delta'] < 0 ? 'overdue' : '' ?>"><?= (float) $m['delta'] > 0 ? '+' : '' ?><?= e(rtrim(rtrim($m['delta'], '0'), '.') ?: '0') ?></td><td><?= e(rtrim(rtrim($m['qty_after'], '0'), '.') ?: '0') ?></td><td><?= e(STOCK_REASONS[$m['reason']]) ?><?= $m['rref'] ? ' · ' . e($m['rref']) : '' ?><?= $m['note'] ? '<br><span class="muted">' . e($m['note']) . '</span>' : '' ?></td><td><?= e($m['uname'] ?? '—') ?></td></tr><?php endforeach; ?>
<?php if (!$moves): ?><tr><td colspan="5" class="muted">No movements yet.</td></tr><?php endif; ?></table></div></div></div>
